installer-gui-script.script:
function checkRunning() {
  if (system.run('/usr/bin/pgrep', '-f', '^.*/Santu Infinite Canvas.app/Contents/MacOS/') == 0) {
    my.result.type = 'Fatal';
    my.result.message = '请先退出 Santu Infinite Canvas，再重新打开安装器。画布、图片和 API 设置会保留。';
    return false;
  }
  return true;
}
